def fizzbuzz(n):
    resultado = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            resultado.append('FizzBuzz')
        elif i % 3 == 0:
            resultado.append('Fizz')
        elif i % 5 == 0:
            resultado.append('Buzz')
        else:
            resultado.append(str(i))
    return resultado

def es_palindromo(s):
    s_limpia = ''.join(c for c in s if c.isalnum()).lower()
    return s_limpia == s_limpia[::-1]

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def buscar(lista, x):
    l = 0
    r = len(lista) - 1
    while l <= r:
        m = (l + r) // 2
        if lista[m] == x:
            return m
        elif lista[m] < x:
            l = m + 1
        else:
            r = m - 1
    return -1

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        valor = item[clave]
        if valor not in resultado:
            resultado[valor] = []
        resultado[valor].append(item)
    return resultado

def rotar(lista, n):
    if not lista:
        return []
    n = n % len(lista)
    return lista[-n:] + lista[:-n]

def a_romano(n):
    numeros_romanos = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"),
        (1, "I")
    ]
    resultado = []
    while n > 0:
        for valor, simbolo in numeros_romanos:
            if n >= valor:
                resultado.append(simbolo)
                n -= valor
    return "".join(resultado)

def desde_romano(s):
    numeros = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }
    valor = 0
    i = 0
    while i < len(s):
        if s[i] in numeros:
            if i + 1 < len(s) and s[i+1] in numeros and numeros[s[i+1]] > numeros[s[i]]:
                valor += numeros[s[i+1]] - numeros[s[i]]
                i += 2
            else:
                valor += numeros[s[i]]
                i += 1
        else:
            i += 1
    return valor

def mayor_racha(lista):
    if not lista:
        return None

    max_elemento = None
    max_longitud = -1

    i = 0
    while i < len(lista):
        elemento = lista[i]
        j = i
        while j < len(lista) and lista[j] == elemento:
            j += 1
        longitud = j - i

        if longitud > max_longitud:
            max_elemento = elemento
            max_longitud = longitud
        i = j

    return (max_elemento, max_longitud)

def a_camel(s):
    words = s.split('_')
    return words[0] + ''.join(word[0].upper() + word[1:] for word in words[1:])

def a_snake(s):
    result = []
    for char in s:
        if char.isupper():
            result.append('_')
        result.append(char.lower())
    return ''.join(result).lstrip('_')

def primos(n):
    if n < 2:
        return []
    primos_list = []
    for i in range(2, n + 1):
        if all(i % j != 0 for j in range(2, int(i ** 0.5) + 1)):
            primos_list.append(i)
    return primos_list

def mcd(a, b):
    if a == 0:
        return b
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

def fusionar(intervalos):
    if not intervalos:
        return []

    # Ordenar por inicio; si los intervalos ya están ordenados, esto no causa un problema
    intervalos = sorted(intervalos, key=lambda x: x[0])

    fusionados = [intervalos[0]]

    for inicio, fin in intervalos[1:]:
        ultimo_inicio, último_fin = fusionados[-1]
        if inicio <= último_fin:
            # Fusionar: actualizar el fin del último intervalo
            fusionados[-1] = (ultimo_inicio, max(último_fin, fin))
        else:
            # No hay solapamiento, añadir nuevo intervalo
            fusionados.append((inicio, fin))

    return fusionados

def es_anagrama(a, b):
    def normalizar(texto):
        return sorted(letra for letra in texto.lower() if letra.isalpha())

    return normalizar(a) == normalizar(b)

def comprimir(s):
    if not s:
        return s

    compres = []
    contador = s[0]
    count = 1

    for char in s[1:]:
        if char == contador:
            count += 1
        else:
            compres.append((contador, count))
            contador = char
            count = 1
    compres.append((contador, count))

    comprimido = ''.join(f"{char}{n}" for char, n in compres)

    return comprimido if len(comprimido) < len(s) else s

def balanceado(texto):
    if texto == "":
        return True

    parentes = {'(': ')', '{': '}', '[': ']'}
    stack = []

    for char in texto:
        if char in parentes:
            stack.append(char)
        elif char in parentes.values() and stack:
            top = stack.pop()
            if parentes[top] == char:
                continue
            else:
                return False
        else:
            return False

    return len(stack) == 0

def transpuesta(matriz):
    if not matriz:
        return []
    n = len(matriz)
    resultados = []
    for i in range(len(matriz[0])):
        fila = []
        for j in range(n):
            if matriz[j] and matriz[j][i] is not None:
                fila.append(matriz[j][i])
            else:
                fila.append(None)
        resultados.append(fila)
    return resultados

def raiz_digital(n):
    while n >= 10:
        suma = 0
        while n > 0:
            suma += n % 10
            n //= 10
        n = suma
    return n

def sin_duplicados(lista):
    resultado = []
    for elemento in lista:
        if elemento not in resultado:
            resultado.append(elemento)
    return resultado

def n_esimo_mayor(lista, n):
    if n <= 0:
        return None
    distinct_values = sorted(set(lista), reverse=True)
    if len(distinct_values) < n:
        return None
    return distinct_values[n - 1]

def formatear_bytes(n):
    if n == 0:
        return '0 B'
    units = ['B', 'KB', 'MB', 'GB']
    for i in range(len(units)):
        unit = units[i]
        value = n / (1024 ** i)
        if value < 1024:
            if i == 0:
                return f'{int(value)} B'
            decimals = 1
            while value * (10 ** decimals) % 1024 == 0 and decimals < 1:
                decimals += 1
            return f'{value:.{decimals}f} {unit}'
    return f'{n} B'

def _lotes(lista, tamano):
    if not lista:
        return []
    resultados = []
    inicio = 0
    while inicio < len(lista):
        lote_tamano = tamano if inicio + tamano <= len(lista) else len(lista) - inicio
        resultados.append(lista[inicio:inicio + lote_tamano])
        inicio += tamano
    return resultados
